-- =====================================================================
-- FLOTAS — precarga el directorio de RH de Grupo ABSA (84 personas con
-- correo propio confirmado). Cuando cada quien entre por primera vez
-- al portal con ese correo, flota_alta_perfil() copia estos datos a su
-- perfil automaticamente.
--
-- Se excluyeron ~25 personas: sin correo capturado, o choferes que en
-- el Excel comparten el correo de su jefe (no es su correo real) — se
-- dan de alta a mano cuando se sepa su correo verdadero.
--
-- Requiere haber corrido antes 31-flotas-precarga-usuarios.sql y
-- 32-flotas-precarga-sin-vehiculo.sql.
--
-- Ejecutar en: Supabase > SQL Editor > New query > Run
-- =====================================================================

on conflict (correo) do update set
  nombre = excluded.nombre,
  telefono = excluded.telefono,
  puesto = excluded.puesto,
  departamento = excluded.departamento,
  jefe_directo = excluded.jefe_directo,
  licencia = excluded.licencia,
  licencia_vence = excluded.licencia_vence,
  tipo_prestacion = excluded.tipo_prestacion;
